.swiper-slide{
  cursor: pointer;
border-radius: 6px;
overflow: hidden;
opacity: 0.4;
transition: all 0.3s ease;
position: relative;
outline: 1px solid transparent;

&.swiper-slide-thumb-active {
  opacity: 1;
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
}

backdrop-filter: blur(8px);
width: 40px;
height: 40px;
cursor: pointer;
border-radius: 50%;
border: none;
background: color-mix(in srgb, var(--accent) 13%, transparent);
color: var(--slate-400);
outline: 2px solid transparent;
outline-offset: 2px;
transition: all 0.2s ease;
position: absolute;
left: 0;
top: 50%;
transform: translate(0%, -50%);

&::after {
  font-size: 16px;
  font-weight: bold;
}

&:hover {
  background: var(--accent);
  outline-color: var(--acent);
  color: var(--teal-400);
}

&:active {
  background: var(--teal-300);
  outline-color: var(--acent);
  color: var(--teal-200);
}

&.swiper-button-disabled {
  opacity: 0.2;
cursor:not-allowed;
  &:hover {
    outline-color: transparent;
    background: color-mix(in srgb, var(--accent) 13%, transparent);
    color: var(--slate-400);
  }

  &:active {
    outline-color: transparent;
    background: color-mix(in srgb, var(--accent) 13%, transparent);
    color: var(--slate-400);
