/* @component: .double-slider-section */
function initDoubleSwiper() {
  if (typeof Swiper !== 'undefined') {
    // 1. Миниатюры с брейкпоинтами
    const swiperLow = new Swiper('.swiperDoubleLow', {
      spaceBetween: 10,
      slidesPerView: 3, // по умолчанию для мобилок
      freeMode: true,
      watchSlidesProgress: true,
      navigation: {
        nextEl: '.Low-prev', 
        prevEl: '.Low-next',
      },
      breakpoints: {
        640: {
          slidesPerView: 4,
          spaceBetween: 12,
        }
      },
      observer: true,
      observeParents: true,
    });

    // 2. Основной слайдер
    new Swiper('.swiperDoubleTop', {
      spaceBetween: 10,
      slidesPerView: 1,
      loop: true,
      speed: 600,
      thumbs: {
        swiper: swiperLow,
      },
      grabCursor: true,
      observer: true,
      observeParents: true,
    });
  } else {
    setTimeout(initDoubleSwiper, 150);
  }
}

if (!document.getElementById('swiper-css')) {
  const link = document.createElement('link');
  link.id = 'swiper-css';
  link.rel = 'stylesheet';
  link.href = 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.css';
  document.head.appendChild(link);
}

if (!document.getElementById('swiper-js')) {
  const script = document.createElement('script');
  script.id = 'swiper-js';
  script.src = 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js';
  script.onload = initDoubleSwiper;
  document.head.appendChild(script);
} else {
  initDoubleSwiper();
}
